{"version":3,"file":"main.jsdbx","sources":["../../src/client/services/LMSService.js","../../src/client/components/CourseList.jsx","../../src/client/components/CourseViewer.jsx","../../src/client/components/LessonViewer.jsx","../../src/client/components/CourseList.css","../../src/client/App.css","../../src/client/main.jsx","../../src/client/App.jsx"],"sourcesContent":["export class LMSService {
  constructor() {
    this.baseUrl = '/api/now/table';
    this.headers = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      'X-UserToken': window.g_ck
    };
  }

  // Courses
  async getCourses(filters = {}) {
    const searchParams = new URLSearchParams(filters);
    searchParams.set('sysparm_display_value', 'all');
    searchParams.set('sysparm_limit', '100');
    searchParams.set('sysparm_order_by', 'title');

    try {
      const response = await fetch(`${this.baseUrl}/x_1879300_learning_courses?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch courses: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching courses:', error);
      throw error;
    }
  }

  async getCourse(courseId) {
    try {
      const response = await fetch(`${this.baseUrl}/x_1879300_learning_courses/${courseId}?sysparm_display_value=all`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch course: ${response.status}`);
      }

      const data = await response.json();
      return data.result;
    } catch (error) {
      console.error('Error fetching course:', error);
      throw error;
    }
  }

  // Lessons
  async getLessonsForCourse(courseId) {
    try {
      const searchParams = new URLSearchParams({
        sysparm_query: `course=${courseId}`,
        sysparm_display_value: 'all',
        sysparm_order_by: 'order_sequence'
      });

      const response = await fetch(`${this.baseUrl}/x_1879300_learning_lessons?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch lessons: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching lessons:', error);
      throw error;
    }
  }

  async getLesson(lessonId) {
    try {
      const response = await fetch(`${this.baseUrl}/x_1879300_learning_lessons/${lessonId}?sysparm_display_value=all`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch lesson: ${response.status}`);
      }

      const data = await response.json();
      return data.result;
    } catch (error) {
      console.error('Error fetching lesson:', error);
      throw error;
    }
  }

  // Materials
  async getMaterialsForLesson(lessonId) {
    try {
      const searchParams = new URLSearchParams({
        sysparm_query: `lesson=${lessonId}`,
        sysparm_display_value: 'all',
        sysparm_order_by: 'order_sequence'
      });

      const response = await fetch(`${this.baseUrl}/x_1879300_learning_materials?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch materials: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching materials:', error);
      throw error;
    }
  }

  // Assessments
  async getAssessmentsForLesson(lessonId) {
    try {
      const searchParams = new URLSearchParams({
        sysparm_query: `lesson=${lessonId}^active=true`,
        sysparm_display_value: 'all'
      });

      const response = await fetch(`${this.baseUrl}/x_1879300_learning_assessments?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch assessments: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching assessments:', error);
      throw error;
    }
  }

  async getAssessmentsForCourse(courseId) {
    try {
      const searchParams = new URLSearchParams({
        sysparm_query: `course=${courseId}^active=true`,
        sysparm_display_value: 'all'
      });

      const response = await fetch(`${this.baseUrl}/x_1879300_learning_assessments?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch course assessments: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching course assessments:', error);
      throw error;
    }
  }

  async getAssessment(assessmentId) {
    try {
      const response = await fetch(`${this.baseUrl}/x_1879300_learning_assessments/${assessmentId}?sysparm_display_value=all`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch assessment: ${response.status}`);
      }

      const data = await response.json();
      return data.result;
    } catch (error) {
      console.error('Error fetching assessment:', error);
      throw error;
    }
  }

  async getQuestionsForAssessment(assessmentId) {
    try {
      const searchParams = new URLSearchParams({
        sysparm_query: `assessment=${assessmentId}`,
        sysparm_display_value: 'all',
        sysparm_order_by: 'order_sequence'
      });

      const response = await fetch(`${this.baseUrl}/x_1879300_learning_questions?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch questions: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching questions:', error);
      throw error;
    }
  }

  async getChoicesForQuestion(questionId) {
    try {
      const searchParams = new URLSearchParams({
        sysparm_query: `question=${questionId}`,
        sysparm_display_value: 'all',
        sysparm_order_by: 'order_sequence'
      });

      const response = await fetch(`${this.baseUrl}/x_1879300_learning_question_choices?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch choices: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching choices:', error);
      throw error;
    }
  }

  // Assessment Attempts
  async startAssessment(assessmentId) {
    try {
      const response = await fetch(`${this.baseUrl}/x_1879300_learning_assessment_attempts`, {
        method: 'POST',
        headers: this.headers,
        body: JSON.stringify({
          assessment: assessmentId,
          user: window.g_user.userID,
          attempt_number: 1, // This should be calculated properly
          started_at: new Date().toISOString(),
          status: 'in_progress'
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to start assessment: ${response.status}`);
      }

      const data = await response.json();
      return data.result;
    } catch (error) {
      console.error('Error starting assessment:', error);
      throw error;
    }
  }

  async submitAssessment(attemptId, responses) {
    try {
      // First, save all responses
      for (const response of responses) {
        await this.saveResponse(attemptId, response);
      }

      // Then update attempt to submitted
      const updateResponse = await fetch(`${this.baseUrl}/x_1879300_learning_assessment_attempts/${attemptId}`, {
        method: 'PATCH',
        headers: this.headers,
        body: JSON.stringify({
          status: 'submitted',
          submitted_at: new Date().toISOString()
        })
      });

      if (!updateResponse.ok) {
        throw new Error(`Failed to submit assessment: ${updateResponse.status}`);
      }

      return updateResponse.json();
    } catch (error) {
      console.error('Error submitting assessment:', error);
      throw error;
    }
  }

  async saveResponse(attemptId, responseData) {
    try {
      const response = await fetch(`${this.baseUrl}/x_1879300_learning_question_responses`, {
        method: 'POST',
        headers: this.headers,
        body: JSON.stringify({
          attempt: attemptId,
          question: responseData.questionId,
          selected_choice: responseData.selectedChoice || '',
          text_answer: responseData.textAnswer || '',
          true_false_answer: responseData.trueFalseAnswer || '',
          response_order: responseData.order || 1
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to save response: ${response.status}`);
      }

      return response.json();
    } catch (error) {
      console.error('Error saving response:', error);
      throw error;
    }
  }

  async getUserAttempts(assessmentId, userId = null) {
    try {
      const user = userId || window.g_user.userID;
      const searchParams = new URLSearchParams({
        sysparm_query: `assessment=${assessmentId}^user=${user}`,
        sysparm_display_value: 'all',
        sysparm_order_by: 'attempt_number'
      });

      const response = await fetch(`${this.baseUrl}/x_1879300_learning_assessment_attempts?${searchParams}`, {
        method: 'GET',
        headers: this.headers
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch attempts: ${response.status}`);
      }

      const data = await response.json();
      return data.result || [];
    } catch (error) {
      console.error('Error fetching user attempts:', error);
      throw error;
    }
  }
}","import React from 'react';
import './CourseList.css';

export default function CourseList({ courses, onSelectCourse }) {
  const extractDisplayValue = (field) => {
    return typeof field === 'object' ? field.display_value : field;
  };

  const getDifficultyClass = (difficulty) => {
    const level = extractDisplayValue(difficulty);
    return `difficulty-${level}`;
  };

  const formatDuration = (hours) => {
    const duration = parseInt(extractDisplayValue(hours) || 0);
    if (duration === 0) return 'Duration not specified';
    if (duration === 1) return '1 hour';
    return `${duration} hours`;
  };

  return (
    <div className="course-list-container">
      <div className="course-list-header">
        <h2>Available Courses</h2>
        <p>Select a course to begin learning</p>
      </div>

      {courses.length === 0 ? (
        <div className="no-courses">
          <p>No courses are currently available. Please check back later.</p>
        </div>
      ) : (
        <div className="course-grid">
          {courses.map(course => {
            const sysId = typeof course.sys_id === 'object' ? course.sys_id.value : course.sys_id;
            const title = extractDisplayValue(course.title);
            const description = extractDisplayValue(course.description);
            const category = extractDisplayValue(course.category);
            const difficulty = extractDisplayValue(course.difficulty_level);
            const duration = extractDisplayValue(course.estimated_duration_hours);
            const createdBy = extractDisplayValue(course.created_by);

            return (
              <div 
                key={sysId}
                className="course-card"
                onClick={() => onSelectCourse(course)}
              >
                <div className="course-card-body">
                  <h3 className="course-title">{title}</h3>

                  {description && (
                    <p className="course-description">
                      {description.length > 150 ? 
                        `${description.substring(0, 150)}...` : 
                        description
                      }
                    </p>
                  )}

                  <div className="course-tags">
                    {category && (
                      <span className="course-category">{category}</span>
                    )}
                    {difficulty && (
                      <span className={`course-difficulty ${getDifficultyClass(difficulty)}`}>
                        {difficulty}
                      </span>
                    )}
                  </div>

                  <div className="course-meta">
                    <span className="course-duration">
                      {formatDuration(duration)}
                    </span>
                    {createdBy && (
                      <span className="course-author">
                        by {createdBy}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}","import React, { useState, useEffect } from 'react';

export default function CourseViewer({ course, service, onSelectLesson }) {
  const [lessons, setLessons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const extractDisplayValue = (field) => {
    return typeof field === 'object' ? field.display_value : field;
  };

  const extractValue = (field) => {
    return typeof field === 'object' ? field.value : field;
  };

  useEffect(() => {
    loadLessons();
  }, [course]);

  const loadLessons = async () => {
    try {
      setLoading(true);
      setError(null);
      const courseId = extractValue(course.sys_id);
      const lessonsData = await service.getLessonsForCourse(courseId);
      setLessons(lessonsData);
    } catch (err) {
      console.error('Error loading lessons:', err);
      setError('Failed to load lessons. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const title = extractDisplayValue(course.title);
  const description = extractDisplayValue(course.description);
  const category = extractDisplayValue(course.category);
  const difficulty = extractDisplayValue(course.difficulty_level);
  const duration = extractDisplayValue(course.estimated_duration_hours);
  const createdBy = extractDisplayValue(course.created_by);

  if (loading) {
    return <div className="loading">Loading course content...</div>;
  }

  if (error) {
    return (
      <div className="error">
        <p>{error}</p>
        <button onClick={loadLessons}>Retry</button>
      </div>
    );
  }

  return (
    <div className="course-overview">
      <div className="course-header">
        <h1>{title}</h1>
        {description && <p>{description}</p>}

        <div className="course-details">
          {category && <span className="detail-item">Category: {category}</span>}
          {difficulty && <span className="detail-item">Level: {difficulty}</span>}
          {duration && <span className="detail-item">Duration: {duration} hours</span>}
          {createdBy && <span className="detail-item">Created by: {createdBy}</span>}
        </div>
      </div>

      <div className="course-content">
        <h2>Course Content</h2>

        {lessons.length === 0 ? (
          <p>No lessons available for this course.</p>
        ) : (
          <div className="lessons-grid">
            {lessons.map((lesson, index) => {
              const lessonId = extractValue(lesson.sys_id);
              const lessonTitle = extractDisplayValue(lesson.title);
              const lessonDescription = extractDisplayValue(lesson.description);
              const lessonType = extractDisplayValue(lesson.lesson_type);
              const duration = extractDisplayValue(lesson.estimated_duration_minutes);

              return (
                <div 
                  key={lessonId}
                  className="lesson-card"
                  onClick={() => onSelectLesson(lesson)}
                >
                  <div className="lesson-number">{index + 1}</div>
                  <div className="lesson-info">
                    <h4 className="lesson-card-title">{lessonTitle}</h4>
                    <div className="lesson-card-meta">
                      {lessonType && <span>Type: {lessonType}</span>}
                      {duration && <span> • Duration: {duration} minutes</span>}
                    </div>
                    {lessonDescription && (
                      <p className="lesson-card-description">
                        {lessonDescription.length > 100 ? 
                          `${lessonDescription.substring(0, 100)}...` : 
                          lessonDescription
                        }
                      </p>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}","import React, { useState, useEffect } from 'react';

export default function LessonViewer({ lesson, course, service }) {
  const [materials, setMaterials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const extractDisplayValue = (field) => {
    return typeof field === 'object' ? field.display_value : field;
  };

  const extractValue = (field) => {
    return typeof field === 'object' ? field.value : field;
  };

  useEffect(() => {
    loadMaterials();
  }, [lesson]);

  const loadMaterials = async () => {
    try {
      setLoading(true);
      setError(null);
      const lessonId = extractValue(lesson.sys_id);
      const materialsData = await service.getMaterialsForLesson(lessonId);
      setMaterials(materialsData);
    } catch (err) {
      console.error('Error loading materials:', err);
      setError('Failed to load lesson materials.');
    } finally {
      setLoading(false);
    }
  };

  const title = extractDisplayValue(lesson.title);
  const description = extractDisplayValue(lesson.description);
  const content = extractDisplayValue(lesson.content);
  const videoUrl = extractDisplayValue(lesson.video_url);
  const videoTitle = extractDisplayValue(lesson.video_title);
  const duration = extractDisplayValue(lesson.estimated_duration_minutes);
  const author = extractDisplayValue(lesson.author);

  return (
    <div className="lesson-container">
      <div className="lesson-header">
        <h1 className="lesson-title">{title}</h1>
        <div className="lesson-meta">
          {duration && <span>Duration: {duration} minutes</span>}
          {author && <span>Author: {author}</span>}
        </div>
      </div>

      <div className="lesson-content">
        {description && (
          <div className="lesson-description">
            <p>{description}</p>
          </div>
        )}

        {videoUrl && videoTitle && (
          <div className="video-section">
            <h3 className="video-title">{videoTitle}</h3>
            <div className="video-container">
              <iframe
                src={videoUrl}
                title={videoTitle}
                width="100%"
                height="400"
                frameBorder="0"
                allowFullScreen
              />
            </div>
          </div>
        )}

        {content && (
          <div className="lesson-text">
            <div dangerouslySetInnerHTML={{ __html: content.replace(/\n/g, '<br/>') }} />
          </div>
        )}

        {!loading && materials.length > 0 && (
          <div className="materials-section">
            <h3 className="materials-title">Supporting Materials</h3>
            <div className="materials-list">
              {materials.map(material => {
                const materialId = extractValue(material.sys_id);
                const materialTitle = extractDisplayValue(material.title);
                const materialType = extractDisplayValue(material.material_type);
                const materialUrl = extractDisplayValue(material.url);
                const materialContent = extractDisplayValue(material.content);

                return (
                  <div key={materialId} className="material-item">
                    <div className="material-icon">📄</div>
                    <div className="material-info">
                      <h4 className="material-name">{materialTitle}</h4>
                      <p className="material-type">{materialType}</p>
                      {materialUrl && (
                        <a href={materialUrl} target="_blank" rel="noopener noreferrer">
                          Open Link
                        </a>
                      )}
                      {materialContent && (
                        <div className="material-content">
                          {materialContent}
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {loading && (
          <div className="loading">Loading materials...</div>
        )}

        {error && (
          <div className="error">
            <p>{error}</p>
          </div>
        )}
      </div>
    </div>
  );
}",".course-list-container {
