          <nav className="breadcrumb">
            <button onClick={handleBackToCourses}>All Courses</button>
            {selectedCourse && (
              <>
                <span> / </span>
                {currentView === 'lesson' ? (
                  <button onClick={handleBackToCourse}>
                    {typeof selectedCourse.title === 'object' ? 
                      selectedCourse.title.display_value : 
                      selectedCourse.title}
                  </button>
                ) : (
                  <span>
                    {typeof selectedCourse.title === 'object' ? 
                      selectedCourse.title.display_value : 
                      selectedCourse.title}
                  </span>
                )}
              </>
            )}
            {selectedLesson && (
              <>
                <span> / </span>
                <span>
                  {typeof selectedLesson.title === 'object' ? 
                    selectedLesson.title.display_value : 
                    selectedLesson.title}
                </span>
              </>
            )}
          </nav>
        )}
      </header>

      <main className="lms-main">
        {currentView === 'courses' && (
          <CourseList 
            courses={courses} 
            onSelectCourse={handleSelectCourse} 
          />
        )}

        {currentView === 'course' && selectedCourse && (
          <CourseViewer 
            course={selectedCourse}
            service={svc}
            onSelectLesson={handleSelectLesson}
          />
        )}

        {currentView === 'lesson' && selectedLesson && (
          <LessonViewer 
            lesson={selectedLesson}
            course={selectedCourse}
            service={svc}
          />
        )}
      </main>
    </div>
  );
